#!/usr/bin/env python3
"""
FundiBolt - Patch 004: Global theme, splash screen, auth screens, auth API
Run this from the project ROOT folder (~/FundiBolt):
    cd ~/FundiBolt
    python3 004_theme_splash_auth.py

After running:
  MOBILE:
    cd code/mobile
    npx expo install expo-linear-gradient expo-font expo-splash-screen \\
      @expo-google-fonts/inter @expo-google-fonts/poppins
    npx expo start

  BACKEND:
    cd code/backend
    npm install
    # Run the migration in code/backend/src/db/migrations/001_create_users_table.sql
    # via Supabase SQL editor, or: psql "$DATABASE_URL_DIRECT" -f src/db/migrations/001_create_users_table.sql
    npm run dev
"""

import os
import base64
import json

ROOT = os.getcwd()

def write_file(path, content):
    full_path = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(full_path) or ".", exist_ok=True)
    with open(full_path, "w") as f:
        f.write(content.lstrip("\n"))
    print(f"[written] {path}")

def write_binary(path, b64data):
    full_path = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(full_path) or ".", exist_ok=True)
    with open(full_path, "wb") as f:
        f.write(base64.b64decode(b64data))
    print(f"[written binary] {path}")


LOGO_B64 = ""


