write_file("code/mobile/src/screens/SplashScreen.tsx", """
import React, { useEffect, useRef } from "react";
import { View, Image, Animated, StyleSheet, Easing } from "react-native";
import { useTheme } from "../theme/ThemeContext";

type Props = { onFinish: () => void };

export default function SplashScreen({ onFinish }: Props) {
  const { colors, fontFamily, fontSize } = useTheme();

  const logoScale = useRef(new Animated.Value(0.6)).current;
  const logoOpacity = useRef(new Animated.Value(0)).current;
  const textOpacity = useRef(new Animated.Value(0)).current;
  const textTranslateY = useRef(new Animated.Value(12)).current;
  const glowPulse = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    // Logo entrance
    Animated.parallel([
      Animated.timing(logoOpacity, { toValue: 1, duration: 500, useNativeDriver: true }),
      Animated.spring(logoScale, { toValue: 1, friction: 5, tension: 60, useNativeDriver: true }),
    ]).start();

    // Neon glow breathing loop
    Animated.loop(
      Animated.sequence([
        Animated.timing(glowPulse, { toValue: 1, duration: 1200, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
        Animated.timing(glowPulse, { toValue: 0, duration: 1200, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
      ])
    ).start();

    // Brand text entrance (slightly after logo)
    Animated.sequence([
      Animated.delay(350),
      Animated.parallel([
        Animated.timing(textOpacity, { toValue: 1, duration: 600, useNativeDriver: true }),
        Animated.timing(textTranslateY, { toValue: 0, duration: 600, easing: Easing.out(Easing.cubic), useNativeDriver: true }),
      ]),
    ]).start();

    const timer = setTimeout(onFinish, 2600);
    return () => clearTimeout(timer);
  }, []);

  const ringScale = glowPulse.interpolate({ inputRange: [0, 1], outputRange: [1, 1.25] });
  const ringOpacity = glowPulse.interpolate({ inputRange: [0, 1], outputRange: [0.55, 0.15] });

  return (
    <View style={[styles.container, { backgroundColor: colors.background }]}>
      <View style={styles.logoWrap}>
        {/* Neon glow rings */}
        <Animated.View
          style={[
            styles.glowRing,
            { backgroundColor: colors.neonBlue, transform: [{ scale: ringScale }], opacity: ringOpacity },
          ]}
        />
        <Animated.View
          style={[
            styles.glowRingInner,
            { backgroundColor: colors.neonGreen, transform: [{ scale: ringScale }], opacity: ringOpacity },
          ]}
        />

        <Animated.Image
          source={require("../../assets/logo.png")}
          style={[styles.logo, { opacity: logoOpacity, transform: [{ scale: logoScale }] }]}
          resizeMode="contain"
        />
      </View>

      <Animated.Text
        style={[
          styles.brandText,
          {
            color: colors.textPrimary,
            fontFamily: fontFamily.headingBold,
            fontSize: fontSize.brand,
            opacity: textOpacity,
            transform: [{ translateY: textTranslateY }],
            textShadowColor: colors.neonGreen,
            textShadowRadius: 16,
            textShadowOffset: { width: 0, height: 0 },
          },
        ]}
      >
        FundiBolt
      </Animated.Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  logoWrap: {
    alignItems: "center",
    justifyContent: "center",
    marginBottom: 24,
  },
  glowRing: {
    position: "absolute",
    width: 220,
    height: 220,
    borderRadius: 110,
  },
  glowRingInner: {
    position: "absolute",
    width: 170,
    height: 170,
    borderRadius: 85,
  },
  logo: {
    width: 150,
    height: 150,
  },
  brandText: {
    letterSpacing: 1,
  },
});
""")


